'use strict';
const $=s=>document.querySelector(s), app=$('#app'); let me=null,csrf='',page='dashboard';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
const date=s=>s?new Date(s).toLocaleDateString():'';
const badge=s=>`<span class="badge ${esc(s)}">${esc(String(s).replaceAll('_',' '))}</span>`;
const brand=`<a class="brand" href="#"><span class="brand-symbol"><img src="/assets/postmaster-mark.png" alt="" width="38" height="38"></span>postmaster<span class="muted">.</span></a>`;
async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body?JSON.stringify(body):undefined});const value=await response.json();if(!response.ok)throw Error(value.error||'Request failed');return value;}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000);}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
$('#close-modal').onclick=()=>$('#modal').close();
function input(name,label,value='',type='text',required=true){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;}
function select(name,label,options,value=''){return `<label>${esc(label)}<select name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x.replaceAll('_',' ')];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function formdata(form){return Object.fromEntries(new FormData(form));}
function bind(form,fn){if(typeof form==='string')form=$(form);form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]')||form.querySelector('button');if(button)button.disabled=true;try{await fn(formdata(form),form);}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}};}
function empty(title='Nothing here yet',text='Your activity will appear here as you get started.'){return `<div class="empty"><b>${esc(title)}</b>${esc(text)}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function head(title,description,action=''){return `<div class="pagehead"><div><div class="eyebrow">YOUR MAILROOM, ONLINE</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function publicPage(){app.innerHTML=`<div class="public"><nav>${brand}<div class="links"><a href="#features">Products</a><a href="#industries">Industries</a><a href="#pricing">Pricing</a><a href="#login">Sign in</a><button data-go="register">Get started ↗</button></div></nav><section class="hero"><div><div class="eyebrow">FROM YOUR SCREEN TO THEIR DOOR</div><h1>Real mail.<br>Remarkably simple.</h1><p>Send letters, postcards, and checks from one organized workspace. No printers. No envelopes. More time for what matters.</p><div class="actions"><button data-go="register">Send your first letter ↗</button><a href="#features">Explore the mailroom →</a></div><p class="compact">Create a free account · Pay for the mail you send</p></div><figure class="hero-art"><img src="/assets/postmaster-concept-portrait.png" alt="A digital document flows from a glass screen into a green envelope above a physical mailbox" width="1122" height="1402" fetchpriority="high"><figcaption><span class="dot"></span>From digital thought to doorstep.</figcaption></figure></section><section id="features"><div class="eyebrow">MAKE ROOM FOR BETTER MAIL</div><h2>Everything your next mailing needs.</h2><div class="grid">${[['Letters','Upload a PDF or write a letter. Personalize, review, and schedule your mailing.','letter'],['Postcards','Create a colorful message, select your audience, and choose a postcard size.','postcard'],['Checks','Prepare business checks with approved bank accounts and a clear audit trail.','check']].map(([t,d,k])=>`<div class="card"><div class="mark">${k==='letter'?'✉':k==='postcard'?'▧':'＄'}</div><h2>${t}</h2><p>${d}</p><a href="#register">Start a ${k} →</a></div>`).join('')}</div></section><section id="industries"><h2>Built for the work you do.</h2><div class="grid">${['Legal services','Property management','Nonprofits','Healthcare','Credit repair','Accounting & bookkeeping'].map(x=>`<div class="card"><h3>${x}</h3><p>Keep recipient records, reusable documents, and mailing history together.</p></div>`).join('')}</div></section><section id="pricing"><h2>A plan for every mailroom.</h2><div class="grid">${[['Free','1 user · Letters and postcards · 90-day preview retention'],['Premium','25 users · Approved checks · Custom retention'],['Enterprise','50 users · Team roles · Activity audit']].map(([x,y])=>`<div class="card"><h2>${x}</h2><p>${y}</p><p>Mailing fees apply separately. Contact support for subscription pricing and activation.</p><button data-go="register">Get started</button></div>`).join('')}</div></section><section id="integrations"><h2>Your workflow, connected.</h2><p class="muted">Developer API available. Request assisted setup for Zapier, Clio, FileVine, HubSpot, QuickBooks Online, Xero, and Google Docs.</p></section><footer><span>© ${new Date().getFullYear()} Postmaster</span><a href="#about">About</a><a href="#help">Help center</a><a href="#api-docs">Developer API</a><a href="#terms">Terms</a><a href="#privacy">Privacy</a><a href="#login">Customer dashboard</a></footer></div>`;wireGo();}
function wireGo(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>location.hash=x.dataset.go);}
function auth(mode){let reset=mode.startsWith('reset=');app.innerHTML=`<div class="auth">${brand}<div class="card"><div class="eyebrow">WELCOME TO YOUR MAILROOM</div><h1>${reset?'Reset password':mode==='register'?'A fresh start for your mail.':mode==='forgot'?'Forgot your password?':'Welcome back.'}</h1><form id="auth">${mode==='register'?input('name','Your name')+input('company','Company / workspace','', 'text',false):''}${!reset?input('email','Email address','','email'):''}${mode!=='forgot'?input('password',reset?'New password':'Password','','password'):''}${mode==='login'?input('code','Authenticator code (if enabled)','','text',false):''}<p class="muted compact">${mode==='register'?'Use at least 12 characters for your password.':''}</p><button type="submit">${reset?'Set password':mode==='register'?'Create account':mode==='forgot'?'Send reset link':'Sign in'} →</button></form><p class="compact"><a href="#${mode==='login'?'register':'login'}">${mode==='login'?'Create an account':'Back to sign in'}</a> ${mode==='login'?' · <a href="#forgot">Forgot password?</a>':''}</p></div></div>`;bind('#auth',async b=>{const path=reset?'/password-reset/complete':mode==='forgot'?'/password-reset':'/'+mode;if(reset)b.token=mode.slice(6);let result=await api(path,'POST',b);if(mode==='forgot'){toast(result.message);return;}if(reset){toast(result.message);location.hash='login';return;}csrf=result.csrf;me=await api('/me');location.hash='dashboard';});}
function shell(){const nav=[['dashboard','▦','Overview'],['new-letter','↗','Send mail'],['letters','✉','Letters'],['postcards','▧','Postcards'],['checks','＄','Checks'],['recipients','♧','Address book'],['lists','≡','Mailing lists'],['templates','▤','Templates'],['marketplace','▣','Marketplace'],['billing','◈','Billing'],['integrations','⌘','Integrations'],['settings','⚙','Settings'],['support','?','Help & support']];if(me.user.superadmin)nav.push(['admin','◇','Super admin']);app.innerHTML=`<div class="shell"><aside class="sidebar">${brand}<nav>${nav.map(([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}">${icon} &nbsp; ${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div>${esc(me.user.name)}</div><select id="workspace">${me.workspaces.map(w=>`<option value="${w.id}" ${w.id===me.tenant.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select><p>${esc(me.tenant.plan.toUpperCase())} PLAN · ${esc(me.role)}</p><a href="#" id="logout">Sign out →</a></div></aside><main class="main"><header class="topbar"><span><strong>${esc(me.tenant.name)}</strong> &nbsp;/&nbsp; Your digital mailroom</span><span>${usd(me.tenant.balance)} available &nbsp; · &nbsp; ${esc(me.user.name.split(' ')[0])}</span></header><div class="content" id="content"></div></main></div>`;$('#logout').onclick=async e=>{e.preventDefault();await api('/logout','POST',{});me=null;location.hash='login';};$('#workspace').onchange=async e=>{await api('/workspace','POST',{id:e.target.value});me=await api('/me');route();};}
function mailRows(rows){return table(['Mailing','Recipient','Created','Status','Cost',''],rows.map(x=>[ `<span class="rowtitle">${esc(x.data.description||x.kind+' mailing')}</span><br><small>${esc(x.id.slice(0,8))} · ${esc(x.kind)}</small>`,esc(x.data.recipients[0]?.name)+(x.data.recipients.length>1?` +${x.data.recipients.length-1}`:''),date(x.created),badge(x.status),usd(x.cost),`<button class="secondary" data-mail="${x.id}">View →</button>`]));}
function wireMail(){document.querySelectorAll('[data-mail]').forEach(x=>x.onclick=()=>detail(x.dataset.mail));}
async function dashboard(){const d=await api('/dashboard');$('#content').innerHTML=head('A good day to send something.','Here’s what’s happening in your mailroom.',`<button data-go="new-letter">＋ Create mailing</button>`)+`<div class="welcome"><div><div class="eyebrow">LESS PAPERWORK. MORE POSSIBILITY.</div><h2>Your next delivery starts here.</h2><p>Write a letter, upload your document, or reach an entire mailing list in just a few steps.</p><a href="#new-letter">Let’s send some mail →</a></div><img class="welcome-art" src="/assets/postmaster-concept-portrait.png" alt="" width="130" height="150" loading="lazy"></div><div class="stats">${[['Total mailings',Object.values(d.counts).reduce((a,b)=>a+b,0)],['In progress',(d.counts.queued||0)+(d.counts.preparing||0)+(d.counts.on_the_way||0)],['Delivered',d.counts.delivered||0],['Available balance',usd(d.balance)]].map(([a,b])=>`<div class="stat"><div class="label">${a}</div><div class="number">${b}</div></div>`).join('')}</div><div class="card"><div class="pagehead"><h2>Recent mailings</h2><a href="#letters">View all →</a></div>${d.recent.length?mailRows(d.recent):empty('Your mailroom is ready','Create your first mailing to get started.')}</div><div class="three">${[['Address book','Keep all your recipients organized.','recipients'],['Save a template','Write once. Personalize every time.','templates'],['Build with our API','Bring mail into your existing workflow.','api-docs']].map(([a,b,c])=>`<div class="card"><h3>${a}</h3><p class="compact">${b}</p><a href="#${c}">Explore →</a></div>`).join('')}</div>`;wireGo();wireMail();}
async function mailList(kind){const rows=(await api('/mail')).filter(x=>x.kind===kind);$('#content').innerHTML=head(kind[0].toUpperCase()+kind.slice(1)+'s','Review, track, and manage your mailings.',`<button data-go="new-${kind}">＋ New ${kind}</button>`)+`<div class="card"><div class="table-tools"><input id="search" placeholder="Search recipient or reference…"><select id="status"><option value="">All statuses</option>${[...new Set(rows.map(x=>x.status))].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="mail-table"></div></div>`;const draw=()=>{const query=$('#search').value.toLowerCase(),status=$('#status').value;const filtered=rows.filter(x=>(!status||x.status===status)&&JSON.stringify(x.data).toLowerCase().includes(query));$('#mail-table').innerHTML=filtered.length?mailRows(filtered):empty('No mailings found');wireMail();};$('#search').oninput=draw;$('#status').onchange=draw;draw();wireGo();}
async function detail(id){const x=await api('/mail/'+id);modal(`<div class="eyebrow">MAILING DETAILS · ${esc(x.kind)}</div><h2>${esc(x.data.description||'Your mailing')}</h2>${badge(x.status)}<p class="mono">${esc(x.id)}</p><div class="two"><div><h3>To</h3>${x.data.recipients.map(a=>`<p>${esc(a.name)}<br>${esc(a.street)}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.postal_code)}<br>${esc(a.country)}</p>`).join('')}</div><div><h3>From</h3><p>${esc(x.data.sender.name)}<br>${esc(x.data.sender.street)}<br>${esc(x.data.sender.city)}</p><p>Service: ${esc(x.data.service)}<br>Scheduled: ${esc(new Date(x.scheduled).toLocaleString())}<br>Mailing fee: ${usd(x.cost)}</p>${x.kind==='check'?`<p>Check #${esc(x.data.check_number)} · ${usd(x.data.amount_cents)}<br>Memo: ${esc(x.data.memo)}</p>`:''}</div></div>${x.data.document_id?`<a target="_blank" rel="noopener" href="/api/documents/${x.data.document_id}">Open PDF preview ↗</a>`:`<div class="preview">${esc(merge(x.data.body||'',x.data.recipients[0]))}</div>${x.kind==='letter'?`<p><a target="_blank" rel="noopener" href="/api/mail/${x.id}/print">Download merged letter PDF + address cover ↗</a></p>`:''}`}${x.tracking?`<p>Tracking: <a target="_blank" rel="noopener" href="https://tools.usps.com/go/TrackConfirmAction?tLabels=${encodeURIComponent(x.tracking)}">${esc(x.tracking)} ↗</a></p>`:''}<p class="muted compact">Provider reference: ${esc(x.provider_id||'Awaiting fulfillment')}. Postal delivery estimates and evidence depend on the selected service and fulfillment operator.</p><div class="actions">${x.status==='unpaid'?`<button id="pay-mail">Pay ${usd(x.cost)} & queue</button>`:''}${['unpaid','scheduled','queued'].includes(x.status)?'<button class="secondary" id="cancel-mail">Cancel mailing</button>':''}</div>`);if($('#pay-mail'))$('#pay-mail').onclick=async()=>{try{await api('/mail/'+id+'/pay','POST',{});toast('Payment recorded. Order queued for fulfillment.');$('#modal').close();route();}catch(e){toast(e.message);}};if($('#cancel-mail'))$('#cancel-mail').onclick=async()=>{try{await api('/mail/'+id+'/cancel','POST',{});toast('Cancelled. Eligible mailing fees refunded.');$('#modal').close();route();}catch(e){toast(e.message);}};}
function merge(body,recipient){return body.replace(/\{\{\s*([\w]+)\s*\}\}/g,(_,k)=>String(recipient?.[k]??recipient?.custom?.[k]??''));}
function addressFields(prefix='',a={}){return `<div class="field-grid">${[['name','Full name'],['company','Company (optional)'],['street','Street address'],['street2','Address line 2 (optional)'],['city','City'],['state','State / region'],['postal_code','ZIP / postal code'],['country','Country code']].map(([k,l])=>input(prefix+k,l,a[k]||(k==='country'?'US':''),'text',!['company','street2','state'].includes(k))).join('')}</div>`;}
function readAddress(b,prefix=''){return Object.fromEntries(['name','company','street','street2','city','state','postal_code','country'].map(k=>[k,b[prefix+k]||'']));}
async function composer(kind){const [recipients,senders,lists,templates,docs,banks]=await Promise.all(['recipients','senders','lists','templates'].map(k=>api('/resources/'+k)).concat([api('/documents'),api('/resources/banks')]));let currentDocument='';let lastQuote=null;$('#content').innerHTML=head('Send a '+kind,'A few details. A real-world delivery.')+`<div class="tabs"><a href="#new-letter">Letter</a><a href="#new-postcard">Postcard</a><a href="#new-check">Check</a></div><div class="notice">Mailing prices are operator-configured estimates. Paid orders enter the fulfillment queue. ${kind==='check'?'Check principal is separate from the mailing fee and requires your verified bank fulfillment arrangement.':''}</div><form id="compose"><div class="two"><div><div class="card"><div class="steps">01 / CREATE YOUR ${kind.toUpperCase()}</div>${input('description','Internal reference (optional)','','text',false)}${kind==='check'?`${select('bank_id','Verified bank account',banks.filter(x=>x.data.status==='approved').map(x=>[x.id,x.data.bank_name+' ••••'+x.data.last4]))}${input('amount','Check amount (USD)','','number')}${input('memo','Memo (optional)','','text',false)}${input('check_number','Check number (blank for automatic)','','text',false)}`:''}${select('template','Start from a saved template',[['','Choose a template…'],...templates.map(x=>[x.id,x.data.name])])}<label>${kind==='postcard'?'Postcard text / design notes':'Write your letter'}<textarea name="body" id="body" placeholder="Dear {{name}},&#10;&#10;Write something worth opening…"></textarea></label><div class="actions"><button type="button" class="secondary" id="preview-letter">Preview merge</button><button type="button" class="secondary" id="save-template">Save as template</button></div><p class="muted compact">Personalize with {{name}}, {{company}}, or up to five custom merge fields. Written letters are rendered to printable PDFs with recipient merge fields. Postcard text requires operator artwork preparation.</p><label>Upload PDF ${kind==='check'?'attachment (up to 5 pages)':''}<input type="file" id="pdf" accept="application/pdf"></label><div id="uploaded" class="muted compact"></div>${select('document','Or use an uploaded PDF',[['','No saved PDF'],...docs.map(x=>[x.id,x.name+' ('+x.pages+' pages)'])])}</div><div class="card"><div class="steps">02 / WHO’S IT FOR?</div>${select('mode','Recipient selection',[['manual','Enter one recipient'],['address','Address book'],['list','Mailing list']])}<div id="recipient-manual">${addressFields('to_')}</div><div id="recipient-address" hidden>${select('recipient_id','Saved recipient',recipients.map(x=>[x.id,x.data.name]))}</div><div id="recipient-list" hidden>${select('list_id','Mailing list',lists.map(x=>[x.id,x.data.name]))}</div></div></div><div><div class="card"><div class="steps">03 / RETURN ADDRESS</div>${select('sender_id','Saved sender',[['','Enter a return address'],...senders.map(x=>[x.id,x.data.name])])}<div id="sender-fields">${addressFields('from_')}</div></div><div class="card"><div class="steps">04 / PRINT & DELIVERY</div>${select('service','Mailing service',(kind==='postcard'?['first_class']:['standard','first_class','certified','certified_return_receipt','priority','express']),'first_class')}${kind==='postcard'?select('size','Postcard size',['4x6','6x9']):'<label><input type="checkbox" name="color"> Print in color</label><label><input type="checkbox" name="duplex"> Print double-sided</label><label><input type="checkbox" name="return_envelope"> Include return envelope</label><label><input type="checkbox" name="prepaid_return_envelope"> Include prepaid return envelope</label>'}${input('scheduled','Mailing date (optional, up to 170 days)','','datetime-local',false)}<button type="button" class="secondary" id="quote">Calculate mailing fee</button><div id="quote-result"></div><p class="compact muted">Review all addresses, content, and print settings before creating your order.</p><button type="submit">Create unpaid order →</button></div></div></div></form>`;
$('#compose select[name=mode]').onchange=e=>{['manual','address','list'].forEach(m=>{$('#recipient-'+m).hidden=m!==e.target.value;$('#recipient-'+m).querySelectorAll('input').forEach(i=>i.required=m===e.target.value&&!['to_company','to_street2','to_state'].includes(i.name));});};
$('#compose select[name=sender_id]').onchange=e=>{const sender=senders.find(x=>x.id===e.target.value);$('#sender-fields').innerHTML=addressFields('from_',sender?.data||{});};
$('#compose select[name=template]').onchange=e=>{$('#body').value=templates.find(x=>x.id===e.target.value)?.data.body||'';};
$('#compose select[name=document]').onchange=e=>{currentDocument=e.target.value;};
$('#pdf').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('Maximum PDF size is 15 MB');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const d=await api('/documents','POST',{name:f.name,content:btoa(binary)});currentDocument=d.id;$('#uploaded').textContent=f.name+' · '+d.pages+' pages uploaded';}catch(e){toast(e.message);}};
const payload=()=>{const f=$('#compose'),b=formdata(f);let selected=b.mode==='manual'?[readAddress(b,'to_')]:b.mode==='address'?[recipients.find(x=>x.id===b.recipient_id)?.data]:recipients.filter(x=>(x.data.list_ids||[]).includes(b.list_id)).map(x=>x.data);return {...b,kind,recipients:selected.filter(Boolean),sender:readAddress(b,'from_'),document_id:currentDocument||undefined,scheduled:b.scheduled?new Date(b.scheduled).toISOString():undefined,color:f.color?.checked||false,duplex:f.duplex?.checked||false,return_envelope:f.return_envelope?.checked||false,prepaid_return_envelope:f.prepaid_return_envelope?.checked||false,amount_cents:kind==='check'?Math.round(Number(b.amount)*100):undefined};};
$('#preview-letter').onclick=()=>{const b=payload();modal(`<h2>Content preview</h2><div class="preview">${esc(merge(b.body,b.recipients[0]))}</div><p class="muted compact">Text preview for the first recipient. PDF and print placement are reviewed by fulfillment.</p>`);};
$('#save-template').onclick=async()=>{const name=prompt('Template name');if(!name)return;try{await api('/resources/templates','POST',{name,body:$('#body').value});toast('Template saved');}catch(e){toast(e.message);}};
$('#quote').onclick=async()=>{try{lastQuote=await api('/quote','POST',payload());$('#quote-result').innerHTML=`<h2>${usd(lastQuote.total_cents)}</h2><p class="compact">${lastQuote.recipients} recipient(s) · ${lastQuote.pages} page(s) · ${usd(lastQuote.unit_cents)} each</p>`;}catch(e){toast(e.message);}};
bind('#compose',async()=>{const result=await api('/mail','POST',payload());toast('Order created. Review and pay when ready.');location.hash=kind+'s';await detail(result.id);});}
async function resources(kind){const rows=await api('/resources/'+kind);const titles={recipients:'Address book',senders:'Return addresses',lists:'Mailing lists',templates:'Templates',banks:'Bank accounts',tickets:'Support tickets'};$('#content').innerHTML=head(titles[kind],kind==='banks'?'Register bank references for operator verification. Do not enter full account or routing numbers.':'Keep your mailing information ready to reuse.',`<button id="add-resource">＋ Add ${kind==='recipients'?'recipient':kind.slice(0,-1)}</button>`)+(kind==='recipients'?'<div class="tabs"><a href="#recipients">Recipients</a><a href="#senders">Return addresses</a><a href="#lists">Mailing lists</a><a href="/api/export" download="recipients.csv">Export CSV ↓</a></div>':'')+(kind==='lists'?'<div class="card"><h3>Bring your audience with you.</h3><p class="compact muted">Import up to 1,000 recipients from CSV. Columns: name, company, street, street2, city, state, postal_code, country, custom_1 through custom_5.</p><button id="import-csv" class="secondary">Import CSV</button></div>':'')+`<div class="card">${rows.length?table(['Name','Details','Updated','Actions'],rows.map(x=>[esc(x.data.name||x.data.subject||x.data.bank_name||'Record'),esc(x.data.street||x.data.body?.slice(0,75)||x.data.company||'')+(x.data.status?' '+badge(x.data.status):''),date(x.updated),`<button class="secondary" data-edit="${x.id}">Edit</button><button class="secondary" data-delete="${x.id}">Delete</button>${kind==='lists'?`<a href="/api/export?list=${x.id}" download="mailing-list.csv">Export</a>`:''}`])):empty('Your '+titles[kind].toLowerCase()+' starts here','Add your first record to make future mailings faster.')}</div>`;$('#add-resource').onclick=()=>resourceEditor(kind);document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>resourceEditor(kind,rows.find(r=>r.id===x.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(x=>x.onclick=async()=>{if(!confirm('Delete this record?'))return;try{await api('/resources/'+kind+'/'+x.dataset.delete,'DELETE');route();}catch(e){toast(e.message);}});if($('#import-csv'))$('#import-csv').onclick=()=>{modal(`<h2>Import mailing list</h2><form id="import-form">${input('name','List name')}<label>CSV file<input type="file" id="csv-file" accept=".csv,text/csv" required></label><button type="submit">Import recipients</button></form>`);bind('#import-form',async b=>{b.csv=await $('#csv-file').files[0].text();const result=await api('/import','POST',b);toast(result.count+' recipients imported');$('#modal').close();route();});};}
async function resourceEditor(kind,row){const d=row?.data||{},lists=kind==='recipients'?await api('/resources/lists'):[];let fields='';if(['recipients','senders'].includes(kind)){fields=addressFields('',d);if(kind==='recipients')fields+=select('list_id','Mailing list',[['','None'],...lists.map(x=>[x.id,x.data.name])],d.list_ids?.[0])+[1,2,3,4,5].map(i=>input('custom_'+i,'Custom field '+i,d.custom?.['custom_'+i]||'','text',false)).join('');}else if(kind==='templates')fields=input('name','Template name',d.name)+`<label>Content<textarea name="body" required>${esc(d.body||'')}</textarea></label>`;else if(kind==='banks')fields=input('bank_name','Bank name',d.bank_name)+input('company','US company legal name',d.company)+input('last4','Account last four digits',d.last4)+input('provider_reference','Provider account reference (optional)',d.provider_reference,'text',false)+`<div class="notice">A super administrator must independently verify and approve this bank reference. No bank debit or check issuance occurs automatically.</div>`;else if(kind==='tickets')fields=input('subject','Subject',d.subject)+`<label>Message<textarea name="body" required>${esc(d.body||'')}</textarea></label>`;else fields=input('name','Name',d.name);modal(`<h2>${row?'Edit':'Add'} ${kind.slice(0,-1)}</h2><form id="resource-form">${fields}<button type="submit">Save changes</button></form>`);bind('#resource-form',async b=>{if(['recipients','senders'].includes(kind)){b={...d,...readAddress(b),list_ids:b.list_id?[b.list_id]:[],custom:Object.fromEntries(Object.entries(b).filter(([k,v])=>k.startsWith('custom_')&&v))};}await api('/resources/'+kind+(row?'/'+row.id:''),row?'PUT':'POST',{data:b});$('#modal').close();toast('Saved');route();});}
async function billing(){const [ledger,catalog]=await Promise.all([api('/ledger'),api('/catalog')]);$('#content').innerHTML=head('Funds & billing','A clear record of every mailing payment and credit.')+`<div class="two"><div class="card"><div class="eyebrow">AVAILABLE BALANCE</div><p class="price">${usd(me.tenant.balance)}</p><div class="actions">${catalog.payments==='stripe'?'<button id="card-fund">Add funds by card</button>':''}<button id="fund-request" class="secondary">Request funds</button></div><p class="muted compact">${catalog.payments==='stripe'?'Card payments use Stripe hosted checkout. Your balance updates after a verified payment event.':'Funds are credited by an administrator after payment verification. Card checkout requires operator configuration.'}</p></div><div class="card"><div class="eyebrow">YOUR SUBSCRIPTION</div><h2>${esc(me.tenant.plan.toUpperCase())}</h2><p>Mailing charges apply separately from plan fees.</p><button class="secondary" id="plan-request">Request plan change</button></div></div><div class="card"><h2>Payment history</h2>${ledger.length?table(['Date','Description','Amount','Receipt'],ledger.map(x=>[date(x.created),esc(x.reason),usd(x.amount),`<button class="secondary" data-receipt="${x.id}">View receipt</button>`])):empty('No transactions yet')}</div>`;if($('#card-fund'))$('#card-fund').onclick=()=>{modal(`<h2>Add mailing funds</h2><form id="card-form">${input('amount','Amount in USD ($5–$10,000)','','number').replace('type="number"','type="number" step="0.01" min="5" max="10000"')}<button type="submit">Continue to secure checkout</button></form>`);bind('#card-form',async b=>{const d=await api('/billing/checkout','POST',{amount_cents:Math.round(Number(b.amount)*100)});location.href=d.url;});};$('#fund-request').onclick=()=>requestTicket('Add funds / payment instructions');$('#plan-request').onclick=()=>requestTicket('Subscription plan change');document.querySelectorAll('[data-receipt]').forEach(el=>el.onclick=()=>{const x=ledger.find(x=>x.id===el.dataset.receipt);modal(`<div class="receipt"><div class="eyebrow">POSTMASTER · TRANSACTION RECEIPT</div><h2>${usd(x.amount)}</h2><p>${esc(me.tenant.name)}</p><p>${esc(x.reason)}</p><p>Date: ${esc(new Date(x.created).toLocaleString())}</p><p class="mono">Reference: ${esc(x.id)}</p>${x.mail_id?`<p class="mono">Mailing: ${esc(x.mail_id)}</p>`:''}<p class="muted compact">A record of your workspace balance movement. This is not a tax invoice.</p><button id="download-receipt">Download receipt</button></div>`);$('#download-receipt').onclick=()=>download('postmaster-receipt-'+x.id+'.txt',`POSTMASTER TRANSACTION RECEIPT\nWorkspace: ${me.tenant.name}\nReference: ${x.id}\nDate: ${x.created}\nAmount: ${usd(x.amount)}\nDescription: ${x.reason}\nMailing: ${x.mail_id||'—'}\n`);});}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function requestTicket(subject){await resourceEditor('tickets',{data:{subject},id:undefined});const form=$('#resource-form');bind(form,async b=>{await api('/resources/tickets','POST',b);$('#modal').close();toast('Request recorded. Support will review it.');});}
async function integrations(){const items=await api('/resources/integrations');const catalog=await api('/catalog');$('#content').innerHTML=head('Bring mail into your workflow.','Developer access and assisted integration setup.')+`<div class="notice">The developer API is available now. Product-specific OAuth connectors and marketplace add-ons require separate implementation and provider configuration; requesting setup does not connect an account.</div><div class="grid">${catalog.integrations.map(name=>{const x=items.find(x=>x.data.name===name);return `<div class="card"><div class="eyebrow">INTEGRATION</div><h2>${esc(name)}</h2><p class="compact">Connect your existing workflow to Postmaster mailing services.</p>${badge(x?.data.status||'not connected')}<p><button class="secondary" data-integration="${esc(name)}">Request setup</button></p></div>`;}).join('')}<div class="card"><h2>Developer API</h2><p class="compact">Create mail and read status using scoped API tokens.</p><a href="#api-docs">Read API guide →</a></div></div>`;document.querySelectorAll('[data-integration]').forEach(el=>el.onclick=async()=>{try{await api('/resources/integrations','POST',{name:el.dataset.integration});toast('Setup request saved');integrations();}catch(e){toast(e.message);}});}
async function settings(tab='profile'){const tabs=['profile','security','workspace','team','tokens','audit','banks'];$('#content').innerHTML=head('Account settings','Make your workspace work for you.')+`<div class="settings-nav">${tabs.map(x=>`<button class="${tab===x?'':'secondary'}" data-setting="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}<button class="secondary" id="signout">Sign out</button></div><div id="settings-body"></div>`;document.querySelectorAll('[data-setting]').forEach(el=>el.onclick=()=>settings(el.dataset.setting).catch(e=>toast(e.message)));$('#signout').onclick=()=>$('#logout').click();const out=$('#settings-body');
if(tab==='profile'){out.innerHTML=`<div class="card"><h2>Your profile</h2><form id="profile">${input('name','Full name',me.user.name)}${input('email','Email',me.user.email,'email')}<button type="submit">Save profile</button></form></div><div class="card"><h3>Account deletion</h3><p class="compact muted">Submit a request for an administrator to review records, retention obligations, and outstanding orders.</p><button class="secondary" id="delete-account">Request account deletion</button></div>`;bind('#profile',async b=>{await api('/profile','POST',b);toast('Profile updated');me=await api('/me');});$('#delete-account').onclick=async()=>{const password=prompt('Enter your password to request account deletion');if(!password)return;try{const r=await api('/delete-account','POST',{password});toast(r.message);}catch(e){toast(e.message);}};}
if(tab==='security'){out.innerHTML=`<div class="two"><div class="card"><h2>Change password</h2><form id="password-form">${input('current','Current password','','password')}${input('password','New password (12+ characters)','','password')}<button type="submit">Update password</button></form></div><div class="card"><h2>Two-factor authentication</h2><p>${me.two_factor?'Enabled':'Not enabled'}. Use an authenticator app for a second sign-in factor.</p><form id="totp-form">${input('password','Confirm password','','password')}${input('code','Authenticator code','','text',false)}<div id="secret"></div><button type="submit">${me.two_factor?'Disable 2FA':'Set up 2FA'}</button></form><p class="compact muted">Keep your authenticator secret in a safe place. If lost, contact your operator for identity-verified recovery.</p></div></div>`;bind('#password-form',async b=>{await api('/password','POST',b);toast('Password updated');$('#password-form').reset();});let secret='';bind('#totp-form',async b=>{if(me.two_factor){await api('/two-factor','POST',{...b,action:'disable'});me=await api('/me');settings('security');return;}if(!secret){const d=await api('/two-factor','POST',{...b,action:'setup'});secret=d.secret;$('#secret').innerHTML=`<p>Add this secret to your authenticator app, then enter its six-digit code.</p><pre>${esc(secret)}</pre>`;$('#totp-form button').textContent='Verify & enable';}else{await api('/two-factor','POST',{...b,action:'enable'});me=await api('/me');toast('Two-factor authentication enabled');settings('security');}});}
if(tab==='workspace'){out.innerHTML=`<div class="card"><form id="workspace-settings"><h2>Workspace & retention</h2>${input('name','Workspace name',me.tenant.name)}${input('retention','Document preview retention in days',me.tenant.retention,'number')}<p class="muted compact">Free: 90 days. Premium / Enterprise: 1–1,095 days. Active orders keep their source documents until fulfillment finishes.</p><button type="submit">Save settings</button></form></div><div class="card"><h3>Join another workspace</h3><form id="accept-invite">${input('token','Invitation token')}<button type="submit">Accept invitation</button></form></div>`;bind('#workspace-settings',async b=>{b.retention=Number(b.retention);await api('/settings','POST',b);me=await api('/me');toast('Workspace updated');});bind('#accept-invite',async b=>{await api('/team/accept','POST',b);me=await api('/me');toast('Workspace added');route();});}
if(tab==='team'){const team=await api('/team');out.innerHTML=`<div class="card"><h2>People in your workspace</h2>${table(['Name','Email','Role','Actions'],team.map(u=>[esc(u.name),esc(u.email),badge(u.role),u.role==='owner'?'Workspace owner':`<button class="secondary" data-role="${u.id}">Change role</button><button class="secondary" data-remove="${u.id}">Remove</button>`]))}</div><div class="card"><h3>Invite an existing Postmaster user</h3><form id="invite">${input('email','Email address','','email')}${select('role','Role',['sender','viewer','admin'])}<button type="submit">Create invitation</button></form><p class="compact muted">Free: 1 user · Premium: 25 · Enterprise: 50. Viewers can read; senders can manage mail; administrators manage workspace data; owners manage roles.</p></div>`;bind('#invite',async b=>{const d=await api('/team/invite','POST',b);modal(`<h2>Invitation created</h2><p>Share this token with ${esc(b.email)}. It expires in seven days and must be accepted from that user’s account.</p><pre>${esc(d.invitation_token)}</pre>`);});document.querySelectorAll('[data-role]').forEach(el=>el.onclick=async()=>{const role=prompt('New role: admin, sender, or viewer');if(!role)return;try{await api('/team/'+el.dataset.role,'PUT',{role});settings('team');}catch(e){toast(e.message);}});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=async()=>{if(!confirm('Remove this team member?'))return;try{await api('/team/'+el.dataset.remove,'DELETE');settings('team');}catch(e){toast(e.message);}});}
if(tab==='tokens'){const tokens=await api('/tokens');out.innerHTML=`<div class="card"><h2>Developer tokens</h2><p class="compact muted">Tokens can read workspace records, quote, and create unpaid mail orders. They cannot add funds or pay orders.</p>${tokens.length?table(['Name','Created',''],tokens.map(x=>[esc(x.name),date(x.created),`<button class="secondary" data-revoke="${x.id}">Revoke</button>`])):empty('No API tokens')}<form id="token-form">${input('name','Token name')}<button type="submit">Generate token</button></form><p><a href="#api-docs">Developer documentation →</a></p></div>`;bind('#token-form',async b=>{const d=await api('/tokens','POST',b);modal(`<h2>Copy your token now</h2><p>It will not be displayed again.</p><pre>${esc(d.token)}</pre>`);settings('tokens');});document.querySelectorAll('[data-revoke]').forEach(el=>el.onclick=async()=>{await api('/tokens/'+el.dataset.revoke,'DELETE');settings('tokens');});}
if(tab==='audit'){const audit=await api('/audit');out.innerHTML=`<div class="card"><h2>Workspace activity</h2>${table(['Time','Action','Actor','Details'],audit.map(x=>[esc(new Date(x.created).toLocaleString()),esc(x.action),esc(x.user_id?.slice(0,8)||'System'),esc(x.detail)]))}</div>`;}
if(tab==='banks'){const banks=await api('/resources/banks');out.innerHTML=`<div class="card"><h2>Verified bank references</h2><p class="muted compact">US companies on Premium and Enterprise may prepare checks after independent verification. Only masked account details and provider references are stored.</p>${table(['Bank','Company','Account','Status'],banks.map(x=>[esc(x.data.bank_name),esc(x.data.company),'••••'+esc(x.data.last4),badge(x.data.status)]))}<button id="add-bank">Add bank account reference</button></div>`;$('#add-bank').onclick=()=>resourceEditor('banks');}}
async function support(){const tickets=await api('/resources/tickets');$('#content').innerHTML=head('We’re here to help.','Questions, setup requests, and mailing support.',`<button id="new-ticket">Create support ticket</button>`)+`<div class="three">${[['Sending mail','Upload a PDF or write content, select recipients, review the quote, create an order, then pay from your balance.'],['Delivery & cancellation','Cancel unpaid, scheduled, or queued orders. After processing starts, contact support. Tracking depends on the service and operator.'],['Privacy & regulated data','Request a BAA and security review before uploading protected health information. No HIPAA compliance claim is made by this software.']].map(([a,b])=>`<div class="card"><h3>${a}</h3><p class="compact">${b}</p></div>`).join('')}</div><div class="card"><h2>Your support requests</h2>${tickets.length?table(['Subject','Message','Status','Reply'],tickets.map(x=>[esc(x.data.subject),esc(x.data.body),badge(x.data.status),esc(x.data.reply||'Awaiting review')])):empty('No open questions','Your support requests and replies will appear here.')}</div>`;$('#new-ticket').onclick=()=>resourceEditor('tickets');}
async function adminPage(){const d=await api('/admin/overview');$('#content').innerHTML=head('Platform administration','Manage workspaces, funds, users, verification, and fulfillment.')+`<div class="notice">Live readiness: email ${d.readiness.smtp?'configured':'not configured'} · fulfillment: manual operator workflow · payments: ${esc(d.readiness.payments)}. Approving a bank reference does not connect to a bank or issue checks.</div><div class="stats">${[['Workspaces',d.tenants.length],['Users',d.users.length],['Mailings',d.mail.length],['Open tickets',d.tickets.filter(x=>x.data.status==='open').length]].map(([a,b])=>`<div class="stat"><div class="label">${a}</div><div class="number">${b}</div></div>`).join('')}</div><div class="card"><h2>Workspaces & billing</h2>${table(['Workspace','Plan','Balance','Actions'],d.tenants.map(t=>[esc(t.name),badge(t.plan),usd(t.balance),`<button class="secondary" data-credit="${t.id}">Add credit</button><button class="secondary" data-plan="${t.id}">Change plan</button>`]))}</div><div class="card"><h2>Platform users</h2>${table(['Name','Email','Status','Platform role','Actions'],d.users.map(u=>[esc(u.name),esc(u.email),badge(u.active?'active':'suspended'),badge(u.superadmin?'Super admin':'User'),`<button class="secondary" data-edit-user="${u.id}">Edit profile</button>`+(u.id===me.user.id?'You':`<button class="secondary" data-user="${u.id}" data-active="${!u.active}">${u.active?'Suspend':'Activate'}</button><button class="secondary" data-role-user="${u.id}">${u.superadmin?'Remove super admin':'Promote to super admin'}</button>`)]))}</div><div class="card"><h2>Fulfillment queue</h2>${d.mail.length?table(['Reference','Type / Fee','Status','Recipient','Actions'],d.mail.map(x=>[esc(x.id.slice(0,10)),esc(x.kind)+' · '+usd(x.cost),badge(x.status),esc(x.data.recipients[0]?.name),`<button class="secondary" data-fulfill="${x.id}">Review & update</button>`])):empty('No orders yet')}</div><div class="card"><h2>Bank verification</h2>${d.banks.length?table(['Bank','Company','Last four','Status',''],d.banks.map(x=>[esc(x.data.bank_name),esc(x.data.company),esc(x.data.last4),badge(x.data.status),`<button class="secondary" data-bank="${x.id}">Review</button>`])):empty('No bank verification requests')}</div><div class="card"><h2>Support inbox</h2>${d.tickets.length?table(['Subject','Message','Status',''],d.tickets.map(x=>[esc(x.data.subject),esc(x.data.body),badge(x.data.status),`<button class="secondary" data-ticket="${x.id}">Reply</button>`])):empty('No support requests')}</div>`;
const actionForm=(title,fields,path,extra={})=>{modal(`<h2>${title}</h2><form id="admin-action">${fields}<button type="submit">Save changes</button></form>`);bind('#admin-action',async b=>{if(b.amount_cents)b.amount_cents=Math.round(Number(b.amount_cents)*100);await api('/admin/'+path,'POST',{...b,...extra});$('#modal').close();toast('Saved with audit record');me=await api('/me');adminPage();});};
document.querySelectorAll('[data-edit-user]').forEach(el=>el.onclick=()=>{const u=d.users.find(u=>u.id===el.dataset.editUser);actionForm('Edit user profile',input('name','Name',u.name)+input('email','Email',u.email,'email'),'user-edit',{id:u.id});});
document.querySelectorAll('[data-role-user]').forEach(el=>el.onclick=async()=>{const u=d.users.find(u=>u.id===el.dataset.roleUser);if(!confirm((u.superadmin?'Remove':'Grant')+' super administrator access for '+u.email+'?'))return;try{await api('/admin/user-role','POST',{id:u.id,superadmin:!u.superadmin});toast('Platform role updated');adminPage();}catch(e){toast(e.message);}});
const gatewayButton=document.createElement('button');gatewayButton.textContent='Payment gateways';gatewayButton.onclick=async()=>{try{const g=await api('/gateways');modal('<h2>Payment gateways</h2><p>Use Keys & tokens to replace credentials. Paystack requires a USD-enabled merchant account. Disabling checkout keeps already-paid transactions verifiable.</p>'+table(['Gateway','Readiness','Action'],[['Stripe',g.stripe?'Ready':'Disabled or missing keys','<button data-gateway-toggle="STRIPE_ENABLED" data-enable="'+(!g.stripe)+'">'+(g.stripe?'Disable checkout':'Enable checkout')+'</button>'],['Paystack',g.paystack?'Ready':'Disabled or missing key','<button data-gateway-toggle="PAYSTACK_ENABLED" data-enable="'+(!g.paystack)+'">'+(g.paystack?'Disable checkout':'Enable checkout')+'</button>'],['Manual funding','Operator verifies payment and credits workspace','Use Add credit in platform administration']]));document.querySelectorAll('[data-gateway-toggle]').forEach(el=>el.onclick=async()=>{try{await api('/admin/keys','POST',{key:el.dataset.gatewayToggle,value:el.dataset.enable});$('#modal').close();toast('Gateway setting saved; credentials must also be configured');adminPage();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}};$('#content').prepend(gatewayButton);
const marketButton=document.createElement('button');marketButton.textContent='Manage marketplace';marketButton.onclick=()=>location.hash='marketplace-admin';$('#content').prepend(marketButton);const keysButton=document.createElement('button');keysButton.className='secondary';keysButton.textContent='Keys & tokens';$('#content').prepend(keysButton);keysButton.onclick=async()=>{try{const [keys,tokens]=await Promise.all([api('/admin/keys'),api('/admin/tokens')]);modal('<h2>Keys & tokens</h2><p>Values are hidden after saving. Blank disables a setting, including environment fallback. Changes apply immediately. SMTP uses STARTTLS.</p>'+table(['Setting','Status','Source','Action'],keys.map(k=>[esc(k.key),k.configured?'Configured':'Not configured',esc(k.source),`<button data-provider-key="${esc(k.key)}">Update / disable</button>`]))+'<h3>Workspace API tokens</h3><p>Token secrets cannot be retrieved. Create replacement tokens in the workspace Settings → Tokens.</p>'+table(['Name','Owner','Workspace','Created','Action'],tokens.map(t=>[esc(t.name),esc(t.email),esc(t.workspace),esc(t.created),`<button data-revoke-token="${t.id}">Revoke</button>`])));document.querySelectorAll('[data-provider-key]').forEach(el=>el.onclick=()=>{const key=el.dataset.providerKey;modal(`<h2>${esc(key)}</h2><form id="provider-secret">${key.endsWith('_ENABLED')?select('value','Accept new checkout sessions',[['false','Disabled'],['true','Enabled']]):'<label>New value (blank disables)<input type="password" name="value" autocomplete="new-password" maxlength="4096"></label>'}<button type="submit">Save setting</button></form>`);bind('#provider-secret',async b=>{await api('/admin/keys','POST',{key,value:b.value||''});$('#provider-secret').reset();$('#modal').close();toast('Setting saved');adminPage();});});document.querySelectorAll('[data-revoke-token]').forEach(el=>el.onclick=async()=>{if(!confirm('Revoke this API token immediately?'))return;try{await api('/admin/revoke-token','POST',{id:el.dataset.revokeToken});$('#modal').close();toast('Token revoked');adminPage();}catch(e){toast(e.message);}});}catch(e){toast(e.message);}};
const auditButton=document.createElement('button');auditButton.className='secondary';auditButton.textContent='View platform audit log';$('#content').prepend(auditButton);auditButton.onclick=async()=>{try{const rows=await api('/admin/audit');modal('<h2>Platform audit log</h2>'+table(['Time','Actor','Action','Details'],rows.map(x=>[esc(x.created),esc(x.user_id||'System'),esc(x.action),esc(x.detail)])));}catch(e){toast(e.message);}};
document.querySelectorAll('[data-credit]').forEach(el=>el.onclick=()=>actionForm('Add workspace credit',input('amount_cents','Amount in USD','','number')+input('reason','Verified payment reference or credit reason'),'credit',{tenant_id:el.dataset.credit}));document.querySelectorAll('[data-plan]').forEach(el=>el.onclick=()=>actionForm('Change plan',select('plan','Subscription plan',['free','premium','enterprise']),'plan',{tenant_id:el.dataset.plan}));document.querySelectorAll('[data-user]').forEach(el=>el.onclick=async()=>{try{await api('/admin/user','POST',{id:el.dataset.user,active:el.dataset.active==='true'});adminPage();}catch(e){toast(e.message);}});document.querySelectorAll('[data-bank]').forEach(el=>el.onclick=()=>actionForm('Verify bank reference',select('status','Verification decision',['approved','rejected'])+input('verification_reference','Independent verification / provider reference'),'bank',{id:el.dataset.bank}));document.querySelectorAll('[data-ticket]').forEach(el=>el.onclick=()=>actionForm('Reply to support request',select('status','Status',['open','resolved'])+'<label>Reply<textarea name="reply" required></textarea></label>','ticket',{id:el.dataset.ticket}));document.querySelectorAll('[data-fulfill]').forEach(el=>el.onclick=()=>{const x=d.mail.find(x=>x.id===el.dataset.fulfill);const transitions={queued:['preparing','failed'],preparing:['on_the_way','failed'],on_the_way:['tracking_available','delivered','failed'],tracking_available:['delivered','failed']};const content=`<h2>Fulfillment review</h2><p class="mono">${esc(x.id)}</p><p>${badge(x.status)} · ${esc(x.kind)} · ${usd(x.cost)}</p><h3>Mailing instructions</h3><pre>${esc(JSON.stringify(x.data,null,2))}</pre>${x.data.document_id?`<a href="/api/admin/document/${x.data.document_id}" target="_blank" rel="noopener">Download source PDF ↗</a>`:x.kind==='letter'?`<a href="/api/admin/print/${x.id}" target="_blank" rel="noopener">Download personalized print PDF ↗</a>`:''}`;if(x.status==='failed'){modal(content+`<form id="refund">${input('reason','Refund reason')}<button type="submit">Refund mailing fee</button></form>`);bind('#refund',async b=>{await api('/admin/refund','POST',{...b,id:x.id});$('#modal').close();adminPage();});}else if(transitions[x.status]){modal(content+`<form id="fulfill">${select('status','Next verified status',transitions[x.status])}${input('provider_id','Fulfillment / postal reference',x.provider_id,'text',false)}${input('tracking','USPS tracking number (if eligible)',x.tracking,'text',false)}${input('note','Evidence / operator note')}<button type="submit">Record fulfillment update</button></form>`);bind('#fulfill',async b=>{await api('/admin/fulfill','POST',{...b,id:x.id});$('#modal').close();adminPage();});}else modal(content+'<p>No fulfillment action is available at this stage.</p>');});}
function article(name){const docs={about:['Mail made simple.','Postmaster brings document preparation, recipients, mailing orders, and fulfillment administration into one workspace. Your operator handles physical production and postal handoff.'],help:['How Postmaster works','Create an account, add a return address and recipients, upload a PDF or write a message, then review and create a mailing order. Fund your balance through your operator and pay to enter fulfillment. Use Help & support for questions.'],terms:['Terms of service — operator draft','This deployment requires the operating company’s legal name, contact address, pricing, fulfillment terms, refund policy, and applicable law before public launch. You must be authorized to use all uploaded documents, recipient information, and bank references. Check mailing requires independently verified business and bank authority. Postal delivery and cancellation depend on the service and processing stage. These draft terms require operator review and completion.'],privacy:['Privacy notice — operator draft','Postmaster stores account details, mailing addresses, uploaded PDFs, order history, activity logs, and masked bank references. Data is used to administer accounts and fulfill mailing instructions. Document preview retention is configurable; backups and transaction records may be retained separately by the operator. Contact your operator to request access, correction, export, or deletion. The operator must publish its identity, subprocessors, security practices, retention schedule, and privacy contact before launch.'], 'api-docs':['Developer API','Create a token under Settings → Tokens. Send Authorization: Bearer YOUR_TOKEN. GET /api/mail reads mailing status; POST /api/quote calculates a price; POST /api/mail creates an unpaid mailing order. Use an Idempotency-Key header when creating mail. API tokens cannot pay orders, credit funds, or administer users.']};const [title,text]=docs[name]||docs.help;const body=`<h1>${title}</h1><p>${text}</p>${name==='api-docs'?`<h2>Create a letter</h2><pre>${esc(JSON.stringify({kind:'letter',body:'Dear {{name}},\nThank you for your business.',service:'first_class',sender:{name:'Your company',street:'100 Main St',city:'Austin',state:'TX',postal_code:'78701',country:'US'},recipients:[{name:'Alex Smith',street:'200 Oak St',city:'Dallas',state:'TX',postal_code:'75201',country:'US'}]},null,2))}</pre><p>Responses and errors are JSON. Prices use integer USD cents. The API creates an unpaid order; an authorized workspace member reviews and pays it from the application.</p>`:''}<a href="#${me?'dashboard':'register'}">${me?'Back to dashboard':'Get started'} →</a>`;if(me)$('#content').innerHTML='<div class="card">'+body+'</div>';else app.innerHTML=`<div class="public-article">${brand}<div class="card">${body}</div></div>`;}
let routeNumber=0;
async function route(){const turn=++routeNumber;page=location.hash.slice(1)||'';try{if(['login','register','forgot'].includes(page)||page.startsWith('reset=')){auth(page);return;}if(!me){try{me=await api('/me');csrf=me.csrf;}catch(e){if(['terms','privacy','about','help','api-docs'].includes(page)){article(page);return;}publicPage();return;}}if(turn!==routeNumber)return;if(!page||['features','industries','pricing','integrations-public'].includes(page))page='dashboard';me=await api('/me');csrf=me.csrf;shell();if(page==='dashboard')await dashboard();else if(['letters','postcards','checks'].includes(page))await mailList(page.slice(0,-1));else if(page.startsWith('new-')&&['letter','postcard','check'].includes(page.slice(4)))await composer(page.slice(4));else if(['recipients','senders','lists','templates','banks'].includes(page))await resources(page);else if(page==='marketplace')await marketplacePage();else if(page==='marketplace-admin')await marketplaceAdmin();else if(page==='billing'){await billing();await gatewayBilling();}else if(page==='settings')await settings();else if(page==='integrations')await integrations();else if(page==='support')await support();else if(page==='admin')await adminPage();else article(page);}catch(e){if($('#content'))$('#content').innerHTML=`<div class="card"><h2>This view is unavailable</h2><p class="error">${esc(e.message)}</p><a href="#dashboard">Back to dashboard →</a></div>`;else toast(e.message);}}
window.addEventListener('hashchange',route);window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'Something went wrong');e.preventDefault();});route();

async function marketplacePage(){
 const [products,orders]=await Promise.all([api('/marketplace'),api('/marketplace/orders')]);
 $('#content').innerHTML=head('Marketplace','Operator-managed services, paid from your workspace wallet.',`<a href="#billing">Add funds →</a>`)+`<div class="grid">${products.length?products.map(p=>`<div class="card"><div class="eyebrow">${esc(p.category)}</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><h3>${usd(p.price)}</h3>${['owner','admin'].includes(me.role)?`<button data-buy-product="${p.id}">Review purchase</button>`:'<p>Workspace owner or admin approval required.</p>'}</div>`).join(''):empty('Catalog coming soon','Your operator has not published any services.')}</div><div class="card"><h2>Your purchases</h2>${table(['Reference','Product','Quantity','Total','Status','Operator note'],orders.map(o=>[esc(o.id),esc(o.name),o.quantity,usd(o.total),badge(o.status),esc(o.note)]))}</div>`;
 document.querySelectorAll('[data-buy-product]').forEach(el=>el.onclick=()=>{const p=products.find(p=>p.id===el.dataset.buyProduct);const requestKey=crypto.randomUUID();modal(`<h2>Review ${esc(p.name)}</h2><p>${esc(p.description)}</p><p>Unit price: ${usd(p.price)}. Paid orders enter operator fulfillment.</p><form id="market-buy">${input('quantity','Quantity (1–100)',1,'number')}<p id="market-total">Total: ${usd(p.price)}</p><button type="submit">Pay from wallet</button></form>`);$('#market-buy [name=quantity]').oninput=e=>$('#market-total').textContent='Total: '+usd(p.price*Number(e.target.value));bind('#market-buy',async b=>{await api('/marketplace/purchase','POST',{product_id:p.id,quantity:Number(b.quantity),unit_price_cents:p.price,request_key:requestKey});$('#modal').close();toast('Purchase recorded; receipt is in Billing');await marketplacePage();});});
}
async function marketplaceAdmin(){
 const d=await api('/admin/marketplace');$('#content').innerHTML=head('Marketplace management','Publish services, update prices, fulfill orders, and refund wallet purchases.',`<button id="market-seed" class="secondary">Populate starter catalog</button><button id="market-new">Add product</button><a href="#admin">Platform admin →</a>`)+`<div class="card">${table(['Product','Category','Price','Visibility','Action'],d.products.map(p=>[esc(p.name),esc(p.category),usd(p.price),p.active?'Published':'Hidden',`<button data-edit-product="${p.id}">Edit</button>`]))}</div><div class="card"><h2>Marketplace orders</h2>${table(['Reference','Workspace','Product','Quantity','Total','Status','Action'],d.orders.map(o=>[esc(o.id),esc(o.tenant_id),esc(o.name),o.quantity,usd(o.total),badge(o.status),['paid','processing'].includes(o.status)?`<button data-market-order="${o.id}">Manage order</button>`:esc(o.note)]))}</div>`;
 $('#market-seed').onclick=async()=>{try{const result=await api('/admin/marketplace/seed','POST',{});toast(result.added+' starter products added; '+result.preserved+' existing products preserved');await marketplaceAdmin();}catch(e){toast(e.message);}};
 const edit=p=>{modal(`<h2>${p.id?'Edit':'Add'} product</h2><form id="market-product">${input('name','Product name',p.name||'')}${input('category','Category',p.category||'Services')}<label>Description<textarea name="description">${esc(p.description||'')}</textarea></label>${input('price','Final unit price in USD',p.price?p.price/100:'','number').replace('type="number"','type="number" step="0.01" min="0.01"')}${select('active','Visibility',[['false','Hidden'],['true','Published']],p.active?'true':'false')}<button type="submit">Save product</button></form>`);bind('#market-product',async b=>{await api('/admin/marketplace/product','POST',{id:p.id,name:b.name,category:b.category,description:b.description,price_cents:Math.round(Number(b.price)*100),active:b.active==='true'});$('#modal').close();await marketplaceAdmin();});};$('#market-new').onclick=()=>edit({});document.querySelectorAll('[data-edit-product]').forEach(el=>el.onclick=()=>edit(d.products.find(p=>p.id===el.dataset.editProduct)));
 document.querySelectorAll('[data-market-order]').forEach(el=>el.onclick=()=>{const o=d.orders.find(o=>o.id===el.dataset.marketOrder);modal(`<h2>Manage ${esc(o.name)}</h2><p>${usd(o.total)} · ${badge(o.status)}</p><form id="market-order">${select('status','Action',o.status==='paid'?['processing','refunded']:['completed','refunded'])}${input('note','Fulfillment evidence / refund reason')}<button type="submit">Record action</button></form>`);bind('#market-order',async b=>{await api('/admin/marketplace/order','POST',{...b,id:o.id});$('#modal').close();await marketplaceAdmin();});});
}
async function gatewayBilling(){
 if(!['owner','admin'].includes(me.role))return;
 const [gateways,pending]=await Promise.all([api('/gateways'),api('/billing/pending')]);
 const box=document.createElement('div');box.className='card';box.innerHTML=`<h2>Payment gateways</h2><p>Stripe: ${gateways.stripe?'Enabled':'Not configured'} · Paystack: ${gateways.paystack?'Enabled (USD)':'Not configured'} · Verified manual funding: Available</p><p>Paystack requires a merchant account enabled for USD. Payments credit the wallet after server verification.</p>${gateways.paystack?'<button id="paystack-fund">Add funds with Paystack</button>':''}<h3>Pending Paystack payments</h3>${table(['Reference','Amount','Action'],pending.map(p=>[esc(p.id),usd(p.amount),`<button data-verify-paystack="${p.id}">Verify payment</button>`]))}`;$('#content').prepend(box);
 if($('#paystack-fund'))$('#paystack-fund').onclick=()=>{modal(`<h2>Add wallet funds</h2><form id="paystack-form">${input('amount','Amount in USD ($5–$10,000)','','number').replace('type="number"','type="number" step="0.01" min="5" max="10000"')}<button type="submit">Continue to Paystack</button></form>`);bind('#paystack-form',async b=>{const result=await api('/billing/paystack','POST',{amount_cents:Math.round(Number(b.amount)*100)});location.href=result.url;});};
 document.querySelectorAll('[data-verify-paystack]').forEach(el=>el.onclick=async()=>{el.disabled=true;try{await api('/billing/paystack/verify','POST',{reference:el.dataset.verifyPaystack});toast('Payment verified');me=await api('/me');await billing();await gatewayBilling();}catch(e){toast(e.message);el.disabled=false;}});
}
